import React from "react";
import { Link } from "react-router-dom";
import "./AchievementCard.css";

function AchievementCard({ type, data }) {
  if (type === "academic") {
    return (
      <article
        className="achievement-card"
        id={`academic-${data.year}-${data.title.slice(0, 20).replace(/\s/g, "-")}`}
      >
        <div className="achievement-card__year">{data.year}</div>
        <div className="achievement-card__content">
          <h3 className="achievement-card__title">
            {data.url ? (
              <a
                href={data.url}
                target="_blank"
                rel="noopener noreferrer"
                className="achievement-card__link"
              >
                {data.title}
                <span className="achievement-card__arrow">↗</span>
              </a>
            ) : (
              data.title
            )}
          </h3>
          <p className="achievement-card__venue">{data.venue}</p>
          {data.authors && (
            <p className="achievement-card__authors">{data.authors}</p>
          )}
          {data.abstract && (
            <p className="achievement-card__description">{data.abstract}</p>
          )}
        </div>
      </article>
    );
  }

  if (type === "technical" || type === "apps") {
    const title = (
      <>
        {data.name}
        <span className="achievement-card__arrow">↗</span>
      </>
    );

    return (
      <article
        className="achievement-card"
        id={`${type}-${data.name.replace(/\s/g, "-")}`}
      >
        <div className="achievement-card__year">
          {data.stars && (
            <span className="achievement-card__stars">
              ★ {data.stars.toLocaleString()}
            </span>
          )}
        </div>
        <div className="achievement-card__content">
          <h3 className="achievement-card__title">
            {data.appPath ? (
              <Link to={data.appPath} className="achievement-card__link">
                {title}
              </Link>
            ) : data.github ? (
              <a
                href={data.github}
                target="_blank"
                rel="noopener noreferrer"
                className="achievement-card__link"
              >
                {title}
              </a>
            ) : (
              data.name
            )}
          </h3>
          <p className="achievement-card__description">{data.description}</p>
          {data.techStack && data.techStack.length > 0 && (
            <div className="achievement-card__tags">
              {data.techStack.map((tech) => (
                <span key={tech} className="achievement-card__tag">
                  {tech}
                </span>
              ))}
            </div>
          )}
        </div>
      </article>
    );
  }

  if (type === "creative") {
    return (
      <article
        className="creative-card"
        id={`creative-${data.title.replace(/\s/g, "-")}`}
      >
        <div className="creative-card__image-wrapper">
          <img
            src={process.env.PUBLIC_URL + data.image}
            alt={data.title}
            className="creative-card__image"
            loading="lazy"
          />
        </div>
        <div className="creative-card__info">
          <h3 className="creative-card__title">{data.title}</h3>
          <p className="creative-card__medium">
            {data.medium}, {data.year}
          </p>
          {data.description && (
            <p className="creative-card__description">{data.description}</p>
          )}
        </div>
      </article>
    );
  }

  return null;
}

export default AchievementCard;
