import React, { useCallback, useEffect, useRef, useState } from "react";
import { useSearchParams } from "react-router-dom";
import "./LlmChat.css";

function hexToBytes(hex) {
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < hex.length; i += 2) {
    bytes[i / 2] = parseInt(hex.substring(i, i + 2), 16);
  }
  return bytes;
}

async function decryptHtml(encData, password) {
  const salt = hexToBytes(encData.salt);
  const iv = hexToBytes(encData.iv);
  const ciphertextWithTag = hexToBytes(encData.ciphertext);

  const keyMaterial = await window.crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(password),
    "PBKDF2",
    false,
    ["deriveKey"]
  );

  const key = await window.crypto.subtle.deriveKey(
    {
      name: "PBKDF2",
      salt,
      iterations: 100000,
      hash: "SHA-256",
    },
    keyMaterial,
    { name: "AES-GCM", length: 256 },
    false,
    ["decrypt"]
  );

  const decrypted = await window.crypto.subtle.decrypt(
    { name: "AES-GCM", iv },
    key,
    ciphertextWithTag
  );

  return new TextDecoder().decode(decrypted);
}

function runInnerScripts(root) {
  root.querySelectorAll("script").forEach((script) => {
    const executable = document.createElement("script");

    Array.from(script.attributes).forEach((attribute) => {
      executable.setAttribute(attribute.name, attribute.value);
    });

    executable.textContent = script.textContent;
    script.replaceWith(executable);
  });
}

function LlmChat() {
  const [searchParams] = useSearchParams();
  const htmlRef = useRef(null);
  const [payload, setPayload] = useState(null);
  const [html, setHtml] = useState("");
  const [manualKey, setManualKey] = useState("");
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState(false);
  const [decryptError, setDecryptError] = useState(false);

  const handleDecrypt = useCallback(async (data, key) => {
    try {
      const decryptedHtml = await decryptHtml(data, key);
      setHtml(decryptedHtml);
      setDecryptError(false);
      document.title = `${data.title} — Xuan Cao`;
    } catch (error) {
      console.error("LLM chat decryption failed:", error);
      setHtml("");
      setDecryptError(true);
    }
  }, []);

  useEffect(() => {
    document.title = "LLM Chat — Xuan Cao";
    const key = searchParams.get("key");

    fetch(`${process.env.PUBLIC_URL}/apps/llm-chat.json`)
      .then((response) => {
        if (!response.ok) throw new Error("LLM chat payload not found");
        return response.json();
      })
      .then(async (data) => {
        setPayload(data);
        setLoading(false);

        if (key) {
          await handleDecrypt(data, key);
        }
      })
      .catch((error) => {
        console.error("Failed to load LLM chat:", error);
        setLoadError(true);
        setLoading(false);
      });
  }, [searchParams, handleDecrypt]);

  useEffect(() => {
    if (!html || !htmlRef.current) return;
    runInnerScripts(htmlRef.current);
  }, [html]);

  const handleSubmit = async (event) => {
    event.preventDefault();
    if (!payload || !manualKey.trim()) return;
    await handleDecrypt(payload, manualKey.trim());
  };

  if (loading) {
    return (
      <div className="llm-chat-page">
        <div className="container container--wide">
          <p className="llm-chat-page__message">Loading...</p>
        </div>
      </div>
    );
  }

  if (loadError || !payload) {
    return (
      <div className="llm-chat-page">
        <div className="container container--wide">
          <p className="llm-chat-page__message">Encrypted chat not found.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="llm-chat-page">
      <div className="container container--wide">
        <header className="llm-chat-page__header fade-in">
          <p className="section-label">Encrypted tool</p>
          <h1 className="page-title">{payload.title}</h1>
          <p className="page-subtitle">
            Enter the page key to decrypt the hidden chat app. Provider API keys
            are entered only after the app is unlocked.
          </p>
        </header>

        {!html ? (
          <section className="llm-chat-page__locked fade-in fade-in--delay-1">
            <div className="llm-chat-page__lock-icon">Locked</div>
            <form className="llm-chat-page__form" onSubmit={handleSubmit}>
              <input
                type="password"
                value={manualKey}
                placeholder="Enter decryption key"
                onChange={(event) => {
                  setManualKey(event.target.value);
                  setDecryptError(false);
                }}
                autoFocus
              />
              <button type="submit">Decrypt</button>
            </form>
            {decryptError && (
              <p className="llm-chat-page__error">
                Incorrect key. Please try again.
              </p>
            )}
          </section>
        ) : (
          <section className="llm-chat-page__unlocked fade-in fade-in--delay-1">
            <div
              ref={htmlRef}
              className="llm-chat-page__html"
              dangerouslySetInnerHTML={{ __html: html }}
            />
          </section>
        )}
      </div>
    </div>
  );
}

export default LlmChat;
