import React, { useState, useEffect } from "react";
import { achievements } from "../../data/achievements";
import AchievementCard from "../../components/AchievementCard/AchievementCard";
import "./Achievements.css";

const CATEGORIES = [
  { key: "academic", label: "Academic" },
  { key: "technical", label: "Open Source" },
  { key: "apps", label: "Apps" },
  { key: "creative", label: "Creative" },
];

function Achievements() {
  const [activeCategory, setActiveCategory] = useState("academic");

  useEffect(() => {
    document.title = "Work — Xuan Cao";
  }, []);

  const showSection = (key) => activeCategory === key;

  return (
    <div className="achievements-page">
      <div className="container">
        <header className="achievements-page__header fade-in" id="achievements-header">
          <h1 className="page-title">Work</h1>
          <p className="page-subtitle">
            A collection of academic research, open-source projects, apps, and
            creative pursuits.
          </p>
        </header>

        {/* Category Tabs */}
        <nav
          className="achievements-page__tabs fade-in fade-in--delay-1"
          role="tablist"
          id="category-tabs"
        >
          {CATEGORIES.map((cat) => (
            <button
              key={cat.key}
              className={`achievements-page__tab ${
                activeCategory === cat.key
                  ? "achievements-page__tab--active"
                  : ""
              }`}
              onClick={() => setActiveCategory(cat.key)}
              role="tab"
              aria-selected={activeCategory === cat.key}
              id={`tab-${cat.key}`}
            >
              {cat.label}
            </button>
          ))}
        </nav>

        <hr className="divider" />

        {/* Academic Section */}
        {showSection("academic") && achievements.academic.length > 0 && (
          <section
            className="achievements-page__section fade-in fade-in--delay-2"
            id="section-academic"
          >
            <div className="achievements-page__list">
              {achievements.academic.map((item, i) => (
                <AchievementCard key={i} type="academic" data={item} />
              ))}
            </div>
          </section>
        )}

        {/* Technical Section */}
        {showSection("technical") && achievements.technical.length > 0 && (
          <section
            className="achievements-page__section fade-in fade-in--delay-2"
            id="section-technical"
          >
            <div className="achievements-page__list">
              {achievements.technical.map((item, i) => (
                <AchievementCard key={i} type="technical" data={item} />
              ))}
            </div>
          </section>
        )}

        {/* Apps Section */}
        {showSection("apps") && achievements.apps.length > 0 && (
          <section
            className="achievements-page__section fade-in fade-in--delay-2"
            id="section-apps"
          >
            <div className="achievements-page__list">
              {achievements.apps.map((item, i) => (
                <AchievementCard key={i} type="apps" data={item} />
              ))}
            </div>
          </section>
        )}

        {/* Creative Section */}
        {showSection("creative") && achievements.creative.length > 0 && (
          <section
            className="achievements-page__section fade-in fade-in--delay-2"
            id="section-creative"
          >
            <div className="achievements-page__gallery">
              {achievements.creative.map((item, i) => (
                <AchievementCard key={i} type="creative" data={item} />
              ))}
            </div>
            <div className="achievements-page__gallery-action">
              <a
                className="achievements-page__gallery-link"
                href="http://xuancao.ca/photography/"
              >
                See more pictures
              </a>
            </div>
          </section>
        )}
      </div>
    </div>
  );
}

export default Achievements;
