import React, { useEffect, useMemo, useState } from "react";
import "./PasswordGenerator.css";

const MIN_LENGTH = 4;
const MAX_LENGTH = 64;

const CHARACTER_SETS = [
  {
    key: "uppercase",
    label: "Uppercase",
    sample: "A-Z",
    chars: "ABCDEFGHIJKLMNOPQRSTUVWXYZ",
  },
  {
    key: "lowercase",
    label: "Lowercase",
    sample: "a-z",
    chars: "abcdefghijklmnopqrstuvwxyz",
  },
  {
    key: "numbers",
    label: "Numbers",
    sample: "0-9",
    chars: "0123456789",
  },
  {
    key: "symbols",
    label: "Symbols",
    sample: "!@#$",
    chars: "!@#$%^&*()-_=+[]{};:,.<>?/",
  },
];

const AMBIGUOUS_CHARACTERS = new Set(Array.from("O0oIl1|`'\";:,."));

const DEFAULT_SETTINGS = {
  length: 18,
  uppercase: true,
  lowercase: true,
  numbers: true,
  symbols: true,
  excludeAmbiguous: true,
};

const PRESETS = [
  {
    key: "balanced",
    label: "Balanced",
    settings: DEFAULT_SETTINGS,
  },
  {
    key: "long",
    label: "Long",
    settings: {
      ...DEFAULT_SETTINGS,
      length: 28,
    },
  },
  {
    key: "pin",
    label: "PIN",
    settings: {
      length: 8,
      uppercase: false,
      lowercase: false,
      numbers: true,
      symbols: false,
      excludeAmbiguous: false,
    },
  },
];

function clampLength(value) {
  const nextLength = Number.parseInt(value, 10);

  if (Number.isNaN(nextLength)) {
    return MIN_LENGTH;
  }

  return Math.min(MAX_LENGTH, Math.max(MIN_LENGTH, nextLength));
}

function getRandomIndex(max) {
  if (max <= 0) return 0;

  const cryptoSource = typeof window !== "undefined" ? window.crypto : null;

  if (cryptoSource && cryptoSource.getRandomValues) {
    const range = 0x100000000;
    const limit = Math.floor(range / max) * max;
    const value = new Uint32Array(1);

    do {
      cryptoSource.getRandomValues(value);
    } while (value[0] >= limit);

    return value[0] % max;
  }

  return Math.floor(Math.random() * max);
}

function pickCharacter(characters) {
  return characters[getRandomIndex(characters.length)];
}

function getSelectedSets(settings) {
  return CHARACTER_SETS.filter((set) => settings[set.key])
    .map((set) => {
      const characters = settings.excludeAmbiguous
        ? Array.from(set.chars)
            .filter((character) => !AMBIGUOUS_CHARACTERS.has(character))
            .join("")
        : set.chars;

      return {
        ...set,
        chars: characters,
      };
    })
    .filter((set) => set.chars.length > 0);
}

function getCharacterPool(settings) {
  const characters = getSelectedSets(settings)
    .map((set) => set.chars)
    .join("");

  return Array.from(new Set(Array.from(characters))).join("");
}

function shuffleCharacters(characters) {
  const shuffled = [...characters];

  for (let index = shuffled.length - 1; index > 0; index -= 1) {
    const swapIndex = getRandomIndex(index + 1);
    [shuffled[index], shuffled[swapIndex]] = [
      shuffled[swapIndex],
      shuffled[index],
    ];
  }

  return shuffled;
}

function generatePassword(settings) {
  const selectedSets = getSelectedSets(settings);

  if (selectedSets.length === 0) {
    return "";
  }

  const length = Math.max(clampLength(settings.length), selectedSets.length);
  const pool = selectedSets.map((set) => set.chars).join("");
  const requiredCharacters = selectedSets.map((set) =>
    pickCharacter(set.chars)
  );
  const remainingCharacters = Array.from(
    { length: length - requiredCharacters.length },
    () => pickCharacter(pool)
  );

  return shuffleCharacters([
    ...requiredCharacters,
    ...remainingCharacters,
  ]).join("");
}

function getStrength(entropyBits, settings) {
  const activeSetCount = CHARACTER_SETS.filter(
    (set) => settings[set.key]
  ).length;

  if (entropyBits < 50 || settings.length < 10) {
    return {
      label: "Weak",
      className: "weak",
      percent: 34,
      summary: "Use more length and character variety.",
    };
  }

  if (entropyBits < 85 || activeSetCount < 3) {
    return {
      label: "Average",
      className: "average",
      percent: 67,
      summary: "Good for low-risk accounts; longer is better.",
    };
  }

  return {
    label: "Strong",
    className: "strong",
    percent: 100,
    summary: "A strong random password for most accounts.",
  };
}

function formatCrackTime(entropyBits) {
  const guessesPerSecond = 10000000000;
  const seconds = Math.pow(2, entropyBits - 1) / guessesPerSecond;

  if (!Number.isFinite(seconds)) return "Centuries";
  if (seconds < 1) return "Instant";
  if (seconds < 60) return `${Math.ceil(seconds)} sec`;
  if (seconds < 3600) return `${Math.ceil(seconds / 60)} min`;
  if (seconds < 86400) return `${Math.ceil(seconds / 3600)} hr`;
  if (seconds < 31536000) return `${Math.ceil(seconds / 86400)} days`;
  if (seconds < 3153600000) return `${Math.ceil(seconds / 31536000)} years`;

  return "Centuries";
}

function PasswordGenerator() {
  const [settings, setSettings] = useState(DEFAULT_SETTINGS);
  const [presetKey, setPresetKey] = useState("balanced");
  const [password, setPassword] = useState(() =>
    generatePassword(DEFAULT_SETTINGS)
  );
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    document.title = "Password Generator - Xuan Cao";
  }, []);

  useEffect(() => {
    setPassword(generatePassword(settings));
    setCopied(false);
  }, [settings]);

  const metrics = useMemo(() => {
    const pool = getCharacterPool(settings);
    const entropyBits =
      pool.length > 0 ? settings.length * Math.log2(pool.length) : 0;
    const strength = getStrength(entropyBits, settings);

    return {
      poolSize: pool.length,
      entropyBits,
      strength,
      crackTime: formatCrackTime(entropyBits),
      activeSetCount: CHARACTER_SETS.filter((set) => settings[set.key]).length,
    };
  }, [settings]);

  const updateSettings = (updates) => {
    setPresetKey("custom");
    setSettings((current) => ({
      ...current,
      ...updates,
    }));
  };

  const updateLength = (value) => {
    updateSettings({ length: clampLength(value) });
  };

  const toggleCharacterSet = (key) => {
    const activeSetCount = CHARACTER_SETS.filter(
      (set) => settings[set.key]
    ).length;

    if (settings[key] && activeSetCount === 1) {
      return;
    }

    updateSettings({ [key]: !settings[key] });
  };

  const applyPreset = (preset) => {
    setPresetKey(preset.key);
    setSettings(preset.settings);
  };

  const generateNewPassword = () => {
    setPassword(generatePassword(settings));
    setCopied(false);
  };

  const copyPassword = async () => {
    if (!password) return;

    try {
      await navigator.clipboard.writeText(password);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1600);
    } catch (error) {
      setCopied(false);
    }
  };

  return (
    <div className="password-generator">
      <div className="container container--wide">
        <header className="password-generator__header fade-in">
          <div>
            <p className="section-label">Interactive tool</p>
            <h1 className="page-title">Password Generator</h1>
            <p className="page-subtitle">
              Generate strong random passwords locally in your browser with
              quick controls for length, character sets, readability, and copy.
            </p>
          </div>
          <div
            className={`password-generator__status password-generator__status--${metrics.strength.className}`}
            role="status"
          >
            <strong>{metrics.strength.label} password</strong>
            <span>
              {Math.round(metrics.entropyBits).toLocaleString()} bits of
              estimated entropy
            </span>
          </div>
        </header>

        <section className="password-generator__toolbar fade-in fade-in--delay-1">
          <div
            className="password-generator__segmented"
            aria-label="Password preset"
          >
            {PRESETS.map((preset) => (
              <button
                key={preset.key}
                type="button"
                className={presetKey === preset.key ? "is-active" : ""}
                onClick={() => applyPreset(preset)}
              >
                {preset.label}
              </button>
            ))}
          </div>

          <div className="password-generator__actions">
            <button type="button" onClick={generateNewPassword}>
              Generate
            </button>
            <button type="button" onClick={copyPassword}>
              {copied ? "Copied" : "Copy"}
            </button>
          </div>
        </section>

        <section className="password-generator__workspace fade-in fade-in--delay-2">
          <div className="password-generator__panel password-generator__panel--main">
            <div className="password-generator__panel-header">
              <h2>Generated password</h2>
              <p>Never stored or sent anywhere</p>
            </div>

            <div className="password-generator__output" aria-live="polite">
              <code>{password}</code>
            </div>

            <div
              className={`password-generator__strength password-generator__strength--${metrics.strength.className}`}
            >
              <div>
                <span>Strength</span>
                <strong>{metrics.strength.label}</strong>
              </div>
              <div className="password-generator__strength-track">
                <span style={{ width: `${metrics.strength.percent}%` }} />
              </div>
              <p>{metrics.strength.summary}</p>
            </div>

            <div className="password-generator__length-control">
              <div>
                <label htmlFor="password-length">Password Length</label>
                <span>{settings.length} characters</span>
              </div>
              <input
                id="password-length"
                type="range"
                min={MIN_LENGTH}
                max={MAX_LENGTH}
                value={settings.length}
                onChange={(event) => updateLength(event.target.value)}
              />
              <input
                type="number"
                min={MIN_LENGTH}
                max={MAX_LENGTH}
                value={settings.length}
                onChange={(event) => updateLength(event.target.value)}
                aria-label="Password length"
              />
            </div>
          </div>

          <aside className="password-generator__panel">
            <div className="password-generator__panel-header">
              <h2>Characters Used</h2>
              <p>{metrics.poolSize.toLocaleString()} possible characters</p>
            </div>

            <div className="password-generator__character-grid">
              {CHARACTER_SETS.map((set) => {
                const activeSetCount = CHARACTER_SETS.filter(
                  (item) => settings[item.key]
                ).length;
                const isOnlyActive = settings[set.key] && activeSetCount === 1;

                return (
                  <label
                    key={set.key}
                    className="password-generator__character-option"
                  >
                    <input
                      type="checkbox"
                      checked={settings[set.key]}
                      disabled={isOnlyActive}
                      onChange={() => toggleCharacterSet(set.key)}
                    />
                    <span>
                      <strong>{set.label}</strong>
                      <em>{set.sample}</em>
                    </span>
                  </label>
                );
              })}
            </div>

            <label className="password-generator__readability">
              <input
                type="checkbox"
                checked={settings.excludeAmbiguous}
                onChange={() =>
                  updateSettings({
                    excludeAmbiguous: !settings.excludeAmbiguous,
                  })
                }
              />
              <span>
                <strong>Avoid ambiguous characters</strong>
                <em>Removes lookalikes such as O, 0, I, l, and 1.</em>
              </span>
            </label>
          </aside>
        </section>

        <section className="password-generator__metrics fade-in fade-in--delay-3">
          <div>
            <span>Length</span>
            <strong>{settings.length.toLocaleString()}</strong>
          </div>
          <div>
            <span>Character sets</span>
            <strong>{metrics.activeSetCount.toLocaleString()}</strong>
          </div>
          <div>
            <span>Entropy</span>
            <strong>
              {Math.round(metrics.entropyBits).toLocaleString()} bits
            </strong>
          </div>
          <div>
            <span>Offline guess estimate</span>
            <strong>{metrics.crackTime}</strong>
          </div>
        </section>
      </div>
    </div>
  );
}

export default PasswordGenerator;
